require_once __DIR__ . '/accounts_common.php';
$user=qbook_require_user();qbook_require_role($user,['ADMIN']);production_require_method('POST');$input=production_input();
accounts_endpoint(function() use($user,$input): array {$type=strtoupper(trim((string)($input['source_type']??'')));$expenseId=(int)($input['source_record_id']??0);$lineId=(int)($input['line_id']??0);if(!in_array($type,['PETTY_CASH_EXPENSE','GENERAL_EXPENSE'],true)||$expenseId<=0||$lineId<=0)accounts_fail('EXPENSE_LINE_SOURCE_NOT_SUPPORTED');$reason=production_clean_text($input['reason']??'',500,'RECLASSIFICATION_REASON_REQUIRED');$db=production_db();return accounts_transaction($db,function() use($db,$user,$input,$type,$expenseId,$lineId,$reason): array {
  $general=$type==='GENERAL_EXPENSE';$expenseTable=$general?'qbook_general_expenses':'qbook_petty_cash_expenses';$lineTable=$general?'qbook_general_expense_lines':'qbook_petty_cash_expense_lines';$historyTable=$general?'qbook_general_expense_line_reclassifications':'qbook_petty_cash_line_reclassifications';$module=$general?'GENERAL_EXPENSE_LINE_RECLASS':'PETTY_CASH_LINE_RECLASS';
  $s=$db->prepare("SELECT * FROM {$expenseTable} WHERE id=? FOR UPDATE");$s->execute([$expenseId]);$expense=$s->fetch();if(!$expense)accounts_fail('EXPENSE_NOT_FOUND',404);if($expense['status']!=='APPROVED'||$expense['journal_id']===null)accounts_fail('EXPENSE_NOT_RECLASSIFIABLE',409);
