  $journal=accounts_post_journal($db,$user,['transaction_date'=>gmdate('Y-m-d'),'description'=>'Line reclassification: '.$reason,'source_module'=>$module,'source_record_id'=>$changeId,'entry_kind'=>'REPLACEMENT','approved_by'=>(int)$user['id']],[['account_id'=>$after['expense_account_id'],'debit_minor'=>$minor,'credit_minor'=>0,'cost_centre_id'=>$after['cost_centre_id'],'client_id'=>$after['client_id'],'project_id'=>$after['project_id'],'mixer_id'=>$after['mixer_id'],'description'=>$after['description']],['account_id'=>(int)$before['expense_account_id'],'debit_minor'=>0,'credit_minor'=>$minor,'cost_centre_id'=>$before['cost_centre_id'],'client_id'=>$before['client_id'],'project_id'=>$before['project_id'],'mixer_id'=>$before['mixer_id'],'description'=>'Reclassify from: '.$before['description']]]);$db->prepare("UPDATE {$historyTable} SET journal_id=? WHERE id=?")->execute([$journal['id'],$changeId]);$db->prepare("UPDATE {$lineTable} SET expense_account_id=?,item_description=?,cost_centre_id=?,client_id=?,project_id=?,mixer_id=? WHERE id=? AND expense_id=?")->execute([$after['expense_account_id'],$after['description'],$after['cost_centre_id'],$after['client_id'],$after['project_id'],$after['mixer_id'],$lineId,$expenseId]);accounts_audit($db,$user,'EXPENSE_LINE_RECLASSIFIED',$type,$expenseId,['line_id'=>$lineId,'version'=>$version,'before'=>$before,'after'=>$after,'journal_id'=>$journal['id'],'asset_impact'=>'0.00','reason'=>$reason]);return ['reclassification'=>['id'=>$changeId,'line_id'=>$lineId,'version'=>$version,'journal'=>$journal],'asset_impact'=>'0.00'];
});});
